                Long v = tree.minimum();
                sb.append(v == null ? "EMPTY" : String.valueOf(v)).append("\n");
            } else if (op.equals("MAX")) {
                Long v = tree.maximum();
                sb.append(v == null ? "EMPTY" : String.valueOf(v)).append("\n");
            } else if (op.equals("HEIGHT")) sb.append(tree.height()).append("\n");
            else {
                List<Long> keys = tree.preorder();
