def gen(rng):
    def fmt(ops):
        return str(len(ops)) + '\n' + '\n'.join(ops)

    tests = []
    tests.append(fmt(['MIN', 'MAX', 'HEIGHT', 'PREORDER', 'DELETE 1', 'SEARCH 1']))
    tests.append(fmt(['INSERT 5', 'INSERT 5', 'SEARCH 5', 'DELETE 5', 'DELETE 5', 'SEARCH 5', 'PREORDER', 'HEIGHT']))
    tests.append(fmt(['INSERT %d' % i for i in range(1, 8)] + ['HEIGHT', 'PREORDER', 'DELETE 1', 'DELETE 2', 'DELETE 3', 'PREORDER', 'HEIGHT', 'MIN', 'MAX']))
    tests.append(fmt(['INSERT 4', 'INSERT 2', 'INSERT 6', 'INSERT 1', 'INSERT 3', 'INSERT 5', 'INSERT 7', 'DELETE 4', 'PREORDER', 'DELETE 6', 'PREORDER', 'HEIGHT']))
    tests.append(fmt(['INSERT -1000000000', 'INSERT 1000000000', 'INSERT 0', 'MIN', 'MAX', 'DELETE 0', 'PREORDER', 'HEIGHT']))

    def small(n, K):
        ops = []
        hc = 0
        while len(ops) < n:
            r = rng.random()
            x = rng.randint(-K, K)
            if r < 0.38:
                ops.append('INSERT %d' % x)
            elif r < 0.52:
                ops.append('SEARCH %d' % x)
            elif r < 0.78:
                ops.append('DELETE %d' % x)
            elif r < 0.83:
                ops.append('MIN')
            elif r < 0.88:
                ops.append('MAX')
            elif r < 0.93 and hc < 20:
                hc += 1
                ops.append('HEIGHT')
            else:
                ops.append('PREORDER')
        return ops

    for K in (3, 5, 8, 12, 20, 30):
        for _ in range(2):
            tests.append(fmt(small(rng.randint(8, 26), K)))

    def big(n, K):
        ops = []
        lst, pos = [], {}
        hc = 0
        printed = 0
        while len(ops) < n:
            r = rng.random()
            if r < 0.45:
                x = rng.randint(1, K)
                ops.append('INSERT %d' % x)
                if x not in pos:
                    pos[x] = len(lst)
                    lst.append(x)
            elif r < 0.65:
                x = rng.choice(lst) if lst and rng.random() < 0.6 else rng.randint(1, K)
                ops.append('SEARCH %d' % x)
            elif r < 0.88:
                x = rng.choice(lst) if lst and rng.random() < 0.8 else rng.randint(1, K)
                ops.append('DELETE %d' % x)
                if x in pos:
                    i = pos.pop(x)
                    last = lst.pop()
                    if last != x:
                        lst[i] = last
                        pos[last] = i
            elif r < 0.91:
                ops.append('MIN')
            elif r < 0.94:
                ops.append('MAX')
            elif r < 0.9407 and hc < 20:
                hc += 1
                ops.append('HEIGHT')
            elif r < 0.9412 and printed + len(lst) <= 190000:
                printed += len(lst)
                ops.append('PREORDER')
        return ops

    tests.append(fmt(big(50000, 10**9)))
    tests.append(fmt(big(50000, 3000)))
    tests.append(fmt(big(50000, 200)))

    # degenerate chain: ascending inserts reach height 1500
    ops = ['INSERT %d' % i for i in range(1, 1501)]
    ops += ['SEARCH %d' % rng.randint(1000, 1600) for _ in range(800)]
    ops += ['HEIGHT', 'MAX', 'MIN', 'DELETE 1', 'DELETE 1500', 'HEIGHT', 'DELETE 700', 'DELETE 701', 'HEIGHT', 'PREORDER']
