    # zig-zag chain: height 1500, deletions of nodes with two children
    ops = []
    for i in range(750):
        ops.append('INSERT %d' % (i + 1))
        ops.append('INSERT %d' % (100000 - i))
    ops += ['HEIGHT'] + ['SEARCH %d' % rng.choice([750, 99251, 375, 99626]) for _ in range(300)]
    ops += ['DELETE 1', 'DELETE 100000', 'HEIGHT', 'DELETE 375', 'DELETE 99626', 'MIN', 'MAX', 'HEIGHT', 'PREORDER']
    tests.append(fmt(ops))

    # descending inserts, then re-insert after deletes
    ops = ['INSERT %d' % (1000 - i) for i in range(1000)]
    ops += ['DELETE %d' % (1000 - i) for i in range(0, 1000, 3)]
    ops += ['INSERT %d' % (1000 - i) for i in range(0, 1000, 6)]
    ops += ['HEIGHT', 'MIN', 'MAX', 'PREORDER']
    tests.append(fmt(ops))
    return tests
